for i in 1 2 3; do curl -s http://127.0.0.1:8941/__reset >/dev/null; node run-task.mjs "$(jq -nc --arg ext $PWD/builds/p440main --arg t "om440-pc$i" '{ext:$ext,display:":41",tag:$t,url:"http://127.0.0.1:8941/",prompt:"新建验收：备注写随手记并回车，正文写好，点刷新，分类选项目，再新建一条笔记，标题写周会纪要，保存。",maxSec:180,after:[{shot:"receipt",wait:800,text:".plan-card"}]}')" 2>&1 | tail -1 | cut -c1-140; echo "SAVES $i $(curl -s http://127.0.0.1:8941/__saves)"; done
